--
-- Table structure for table `cdkey`
--

DROP TABLE IF EXISTS `cdkey`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cdkey` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(255) NOT NULL,
  `type` int(11) NOT NULL COMMENT '类型 0星币 3钻石卡 2金卡 1银卡 ',
  `value` varchar(255) NOT NULL COMMENT '1已使用 -1一次性 0不限次',
  `user` int(11) NOT NULL DEFAULT '-1' COMMENT '使用者',
  `server` int(11) NOT NULL DEFAULT '-1' COMMENT '使用区服（-1无限刷）',
  `start` int(11) NOT NULL COMMENT '开始时间',
  `end` int(11) NOT NULL COMMENT '结束时间',
  `time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=24215 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT;
/*!40101 SET character_set_client = @saved_cs_client */;

